\usepackage{enumitem}
\usepackage{xcolor}
\usepackage{needspace}
\usepackage{microtype}
\pagestyle{empty}
\setlength{\parindent}{0pt}

\definecolor{navy}{RGB}{0,51,102}
\definecolor{mygray}{RGB}{95,100,110}

% Section heading: small caps, navy, ruled; never alone at a page foot
\newcommand{\cvsect}[1]{%
  \par\needspace{4\baselineskip}%
  \vspace{0.75em}%
  {\large\bfseries\color{navy}\scshape #1}%
  \\[-0.55em]%
  {\color{navy!55}\hrule height 0.6pt}%
  \vspace{0.3em}%
}
\newcommand{\cvsub}[1]{\par\needspace{3\baselineskip}\vspace{0.2em}{\bfseries\itshape #1}\par}

% \cventry{dates}{title}{institution}{location}{details}
% One flow, the date on the title line, so text extraction keeps them together.
\newcommand{\cventry}[5]{%
  \par\noindent{\bfseries #2}\hfill{\small\color{mygray}#1}\\*%
  {\small\itshape\color{mygray}#3\ifx&#4&\else, #4\fi}%
  \ifx&#5&\else\\*{\small #5}\fi\par
  \vspace{0.38em}%
}

\begin{document}

\begin{center}
  {\Huge\bfseries\color{navy} Dr Jane Smith}\\[0.35em]
  {\large Postdoctoral Researcher, Computational Neuroscience}\\[0.3em]
  \small \mbox{\href{mailto:j.smith@university.edu}{j.smith@university.edu}} \quad\textbullet\quad \mbox{\href{tel:+442000000000}{+44 20 0000 0000}} \quad\textbullet\quad \mbox{Oxford, UK}\\[0.15em]
  \mbox{\href{https://janesmith.github.io}{janesmith.github.io}} \quad\textbullet\quad \mbox{\href{https://github.com/janesmith}{github.com/janesmith}} \quad\textbullet\quad \mbox{\href{https://orcid.org/0000-0002-1825-0097}{ORCID~0000-0002-1825-0097}}
\end{center}

{\color{navy}\rule{\linewidth}{1.2pt}}

\cvsect{Profile}
Computational modelling of neural circuits, Bayesian inference in sensory processing and machine learning for neuroimaging.

\cvsect{Education}
\cventry{Oct. 2019 -- Sept. 2023}{Ph.D. in Computational Neuroscience}{University of Cambridge}{Cambridge, UK}{Thesis: Probabilistic models of predictive coding in visual cortex}
\cventry{Sept. 2017 -- June 2019}{M.Sc. in Mathematics}{Imperial College London}{London, UK}{}

\cvsect{Experience}
\cventry{Oct. 2023 -- present}{Postdoctoral Research Fellow}{University of Oxford}{Oxford, UK}{Built a Bayesian decoder that cut analysis time for 7T fMRI data by 40\%\\ Leads a team of 3 PhD students and 2 master's interns}

\cvsect{Publications}
\cvsub{Journal articles}
\begin{enumerate}[leftmargin=*, itemsep=2pt, topsep=3pt]
  \item \textbf{Smith, J.} \& Researcher, A. (2023). Efficient coding with correlated neural noise. \textit{PLOS Computational Biology}.
\end{enumerate}
\cvsub{Conference papers}
\begin{enumerate}[leftmargin=*, itemsep=2pt, topsep=3pt]
  \item Chen, L., \textbf{Smith, J.} \& Okafor, N. (2024). Predictive coding as amortised inference. \textit{Advances in Neural Information Processing Systems (NeurIPS)}.
\end{enumerate}
\cvsub{Preprints}
\begin{enumerate}[leftmargin=*, itemsep=2pt, topsep=3pt]
  \item \textbf{Smith, J.} (2025). Sparse priors for laminar fMRI. \textit{bioRxiv}.
\end{enumerate}

\cvsect{Grants and fellowships}
\begin{itemize}[leftmargin=1.2em, itemsep=1pt, topsep=2pt]
  \item 2023 – 2025: Marie Skłodowska-Curie Postdoctoral Fellowship (EUR 215,000)
\end{itemize}

\cvsect{Teaching and supervision}
\begin{itemize}[leftmargin=1.2em, itemsep=1pt, topsep=2pt]
  \item 2024: Lecturer, Bayesian Models of Cognition (M.Sc., 40 students)
  \item 2020 – 2022: Supervisor, Part II Neuroscience, University of Cambridge
\end{itemize}

\cvsect{Invited talks}
\begin{itemize}[leftmargin=1.2em, itemsep=1pt, topsep=2pt]
  \item 2024: Gatsby Computational Neuroscience Unit, London
\end{itemize}

\cvsect{Awards}
\begin{itemize}[leftmargin=1.2em, itemsep=1pt, topsep=2pt]
  \item 2023: Best Thesis Prize, Cambridge Neuroscience
\end{itemize}

\cvsect{Service}
\begin{itemize}[leftmargin=1.2em, itemsep=1pt, topsep=2pt]
  \item Reviewer for PLOS Computational Biology and NeurIPS
\end{itemize}

\cvsect{References}
Prof. Alan Turner, University of Cambridge, a.turner@cam.ac.uk\par

\cvsect{Skills}
\begin{tabular}{@{}lp{0.72\linewidth}}
  \textbf{Programming} & Python, PyTorch, JAX, R\\
  \textbf{Tools} & Git, LaTeX, Slurm, Docker\\
  \textbf{Languages} & English (native), French (B2)\\
\end{tabular}

\end{document}

